import{_ as n,c as a,o as t,ag as i}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"Datenschutz-Optionen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy-choices.md","filePath":"de/guide/privacy-choices.md","lastUpdated":1794112334000}'),r={name:"de/guide/privacy-choices.md"};function s(o,e,d,u,h,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="datenschutz-optionen" tabindex="-1">Datenschutz-Optionen <a class="header-anchor" href="#datenschutz-optionen" aria-label="Permalink to &quot;Datenschutz-Optionen&quot;">​</a></h1><p>Diese Seite beschreibt, wie du Datenschutzanfragen an Nicasa stellst und was du erwarten kannst.</p><h2 id="wofur-diese-seite-gedacht-ist" tabindex="-1">Wofür diese Seite gedacht ist <a class="header-anchor" href="#wofur-diese-seite-gedacht-ist" aria-label="Permalink to &quot;Wofür diese Seite gedacht ist&quot;">​</a></h2><p>Nutze diese Seite, um Auskunft über personenbezogene Daten, Löschung oder Datenübertragbarkeit zu beantragen oder bestimmten Datennutzungen zu widersprechen (zum Beispiel „Nicht verkaufen“-Anfragen, wo anwendbar).</p><p>Hinweis: Nicasa erfasst derzeit keine personenbezogenen Daten und speichert sie nicht (siehe Datenschutzerklärung). Wenn du glaubst, dass wir personenbezogene Daten über dich haben, stelle eine Anfrage und wir werden dem nachgehen.</p><h2 id="so-stellst-du-eine-anfrage" tabindex="-1">So stellst du eine Anfrage <a class="header-anchor" href="#so-stellst-du-eine-anfrage" aria-label="Permalink to &quot;So stellst du eine Anfrage&quot;">​</a></h2><p>Bitte gib bei einer Anfrage die folgenden Informationen an, damit wir sie effizient bearbeiten können:</p><ul><li>Deinen Namen</li><li>Kontakt-E-Mail</li><li>Beschreibung der Anfrage (Auskunft, Löschung, Datenübertragbarkeit oder Widerspruch)</li><li>Alle Angaben, die uns beim Auffinden von Datensätzen helfen (z. B. eine Support-Ticket-ID)</li></ul><p>Sende Anfragen an einen der folgenden Wege:</p><ul><li>E-Mail: <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a></li><li>Datenschutz-Issue eröffnen: <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li></ul><h2 id="antwortzeit" tabindex="-1">Antwortzeit <a class="header-anchor" href="#antwortzeit" aria-label="Permalink to &quot;Antwortzeit&quot;">​</a></h2><p>Wir bemühen uns, gültige Anfragen innerhalb von 30 Tagen zu bestätigen und zu beantworten. Wenn wir mehr Zeit benötigen, informieren wir dich mit einem geschätzten Zeitrahmen.</p><h2 id="wenn-wir-keine-personenbezogenen-daten-haben" tabindex="-1">Wenn wir keine personenbezogenen Daten haben <a class="header-anchor" href="#wenn-wir-keine-personenbezogenen-daten-haben" aria-label="Permalink to &quot;Wenn wir keine personenbezogenen Daten haben&quot;">​</a></h2><p>Da Nicasa so gestaltet ist, dass Bilder lokal verarbeitet und keine Nutzerdaten erfasst werden, werden viele Anfragen mit der Bestätigung abgeschlossen, dass keine personenbezogenen Daten vorliegen. Wenn du Belege dafür vorlegst, dass personenbezogene Daten erfasst wurden, gehen wir dem nach und ergreifen geeignete Maßnahmen.</p><h2 id="nicht-verkaufen-widerspruch" tabindex="-1">Nicht verkaufen / Widerspruch <a class="header-anchor" href="#nicht-verkaufen-widerspruch" aria-label="Permalink to &quot;Nicht verkaufen / Widerspruch&quot;">​</a></h2><p>Wenn du ein Recht deiner Jurisdiktion ausübst (zum Beispiel nach CCPA/CPRA), dem Verkauf zu widersprechen, und glaubst, dass wir deine personenbezogenen Daten verkauft haben, beschreibe die Umstände in deiner Anfrage. Wenn wir keine personenbezogenen Daten verkaufen, bestätigen wir das in unserer Antwort.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Bei Fragen zu diesem Verfahren kontaktiere <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a> oder eröffne ein Issue unter <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a>.</p>',18)])])}const g=n(r,[["render",s]]);export{p as __pageData,g as default};
